1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
43	
44	const PROCESSING_FEE = 5;
45	
46	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
47	
48	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
49	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
50	
51	/** The closed set of insurable item types, each with its base premium in gold. */
52	const BASE_PREMIUMS = {
53	  sword: 100,
54	  amulet: 60,
55	  staff: 80,
56	  potion: 40,
57	  rune: 25,
58	  moonstone: 25,
59	} as const satisfies Record<string, number>;
60	
61	export type ItemType = keyof typeof BASE_PREMIUMS;
62	
63	const isInsurableType = (type: string): type is ItemType => type in BASE_PREMIUMS;
64	
65	/** The MHPCO does not insure what is not in its price list. */
66	const insurableTypeOf = (item: Item): ItemType => {
67	  if (!isInsurableType(item.type)) throw new Error(`Unknown item type: ${item.type}`);
68	  return item.type;
69	};
70	
71	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[insurableTypeOf(item)];
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	/** Groups items by type; "alike" means same type, not same family. */
77	const groupByType = (items: Item[]): Item[][] => {
78	  const types = [...new Set(items.map((item) => item.type))];
79	  return types.map((type) => items.filter((item) => item.type === type));
80	};
81	
82	const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);
83	
84	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
85	
86	/** Three alike components form a block, priced at a special base premium. */
87	const basePremiumOfGroup = (group: Item[]): number =>
88	  group.length === BLOCK_SIZE && group.every(isComponent)
89	    ? BLOCK_BASE_PREMIUM
90	    : sum(group.map(basePremiumOf));
91	
92	const totalBasePremium = (items: Item[]): number =>
93	  sum(groupByType(items).map(basePremiumOfGroup));
94	
95	const CURSE_SURCHARGE_RATE = 0.5;
96	
97	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
98	const HIGH_ENCHANTMENT_THRESHOLD = 5;
99	
100	const isCursed = (item: Item): boolean => item.cursed === true;
101	
102	const isHighlyEnchanted = (item: Item): boolean =>
103	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
104	
105	const itemSurchargeRate = (item: Item): number =>
106	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
107	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
108	
109	/**
110	 * Item-specific surcharges apply to the affected item's own base premium,
111	 * unlike policy-wide modifiers which apply to the policy's total base premium.
112	 *
113	 * NOTE: this uses each item's ungrouped base premium, so a cursed component
114	 * inside a 3-alike block is surcharged against its own 25 G rather than its
115	 * share of the block's 60 G. No test covers that combination yet; the choice
116	 * is unverified, not deliberate.
117	 */
118	const totalItemSurcharges = (items: Item[]): number =>
119	  sum(items.map((item) => basePremiumOf(item) * itemSurchargeRate(item)));
120	
121	const LOYALTY_DISCOUNT_RATE = 0.2;
122	const LOYALTY_THRESHOLD_YEARS = 2;
123	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
124	
125	const isLoyal = (customer: Customer): boolean =>
126	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
127	
128	/**
129	 * Policy-wide modifiers apply to the policy's base premium, not to the item
130	 * surcharges. Returns a signed rate: the first-insurance surcharge less the
131	 * loyalty discount, so a loyal customer's rate can be negative.
132	 */
133	const policyModifierRate = (customer: Customer, isFollowUpContract: boolean): number =>
134	  FIRST_INSURANCE_SURCHARGE_RATE -
135	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
136	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
137	
138	const quotePremium = (
139	  items: Item[],
140	  customer: Customer,
141	  isFollowUpContract: boolean,
142	): number => {
143	  const basePremium = totalBasePremium(items);
144	  const premiumBeforeFee =
145	    basePremium +
146	    totalItemSurcharges(items) +
147	    basePremium * policyModifierRate(customer, isFollowUpContract);
148	  return roundPremium(premiumBeforeFee + PROCESSING_FEE);
149	};
150	
151	const INSURANCE_VALUES: Record<ItemType, number> = {
152	  sword: 1000,
153	  amulet: 600,
154	  staff: 800,
155	  potion: 400,
156	  rune: 250,
157	  moonstone: 250,
158	};
159	
160	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[insurableTypeOf(item)];
161	
162	const DEDUCTIBLE = 100;
163	const CAP_MULTIPLIER = 2;
164	
165	/** Rounds down in the MHPCO's favor. */
166	const roundPayout = (amount: number): number => Math.floor(Number(amount.toFixed(6)));
167	
168	interface Policy {
169	  items: Item[];
170	  remainingCap: number;
171	}
172	
173	const openPolicy = (items: Item[]): Policy => ({
174	  items,
175	  remainingCap: sum(items.map(insuranceValueOf)) * CAP_MULTIPLIER,
176	});
177	
178	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
179	const HALVED_REIMBURSEMENT_RATE = 0.5;
180	const FULL_REIMBURSEMENT_RATE = 1;
181	
182	/** Damage to a heavily enchanted item is only half reimbursed. */
183	const reimbursementRate = (item: Item): number =>
184	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD
185	    ? HALVED_REIMBURSEMENT_RATE
186	    : FULL_REIMBURSEMENT_RATE;
187	
188	/** A damage paired with the specific insured item it was matched against. */
189	interface MatchedDamage {
190	  damage: Damage;
191	  item: Item;
192	}
193	
194	/**
195	 * A damage names only an item type, so the insured item it refers to — and
196	 * hence its enchantment and material — has to be looked up on the policy.
197	 * Each damage consumes a distinct insured item: two sword damages need two
198	 * insured swords, otherwise the whole claim is rejected.
199	 */
200	const matchDamagesToInsuredItems = (policy: Policy, damages: Damage[]): MatchedDamage[] => {
201	  const unclaimed = [...policy.items];
202	  return damages.map((damage) => {
203	    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
204	    if (index === -1) throw new Error(`Item not insured: ${damage.itemType}`);
205	    return { damage, item: unclaimed.splice(index, 1)[0] };
206	  });
207	};
208	
209	/** The deductible is withheld once per damaged item, not once per incident. */
210	const reimbursementAfterDeductible = ({ damage, item }: MatchedDamage): number =>
211	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
212	
213	/** Draws down the policy's remaining cap as a side effect. */
214	const settleClaim = (policy: Policy, incident: Incident): Result => {
215	  const matched = matchDamagesToInsuredItems(policy, incident.damages);
216	  const claimedBeforeCap = sum(matched.map(reimbursementAfterDeductible));
217	  const payout = roundPayout(Math.min(claimedBeforeCap, policy.remainingCap));
218	  policy.remainingCap -= payout;
219	  return { payout, remainingCap: policy.remainingCap };
220	};
221	
222	export const runScenario = (scenario: Scenario): { results: Result[] } => {
223	  const policies = new Map<number, Policy>();
224	  let quotesSoFar = 0;
225	
226	  const results = scenario.steps.map((step, stepIndex) => {
227	    if (step.op === "quote") {
228	      const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
229	      quotesSoFar += 1;
230	      policies.set(stepIndex, openPolicy(step.items));
231	      return { premium };
232	    }
233	    const policy = policies.get(step.policy);
234	    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
235	    return settleClaim(policy, step.incident);
236	  });
237	
238	  return { results };
239	};
