const priceOf = (item: Item) => {
  if (!isInsurableType(item.type)) throw new Error(`Unknown item type: ${item.type}`);
  return PRICE_LIST[item.type];
};

const basePremiumOf = (item: Item): number => priceOf(item).basePremium;

